# Let me think about this from a different angle
# What if the rule is: 8s and 1s propagate across the grid,
# following the edges of the 3s?

# Let me see where 8s appear in output by looking at input positions
# and see what special property they have

# First, let me locate ALL 3s in the input
print("All 3 positions in demo input:")
for i in range(14):
    for j in range(29):
        if demo_input[i][j] == 3:
            print(f"  ({i},{j})")

print("\nAll 8 and 1 positions in demo input:")
for i in range(14):
    for j in range(29):
        if demo_input[i][j] in [1, 8]:
            print(f"  ({i},{j}): {demo_input[i][j]}")

# Count the values
input_3_count = sum(sum(row.count(3) for row in demo_input))
output_8_count = sum(sum(row.count(8) for row in demo_output))
output_1_count = sum(sum(row.count(1) for row in demo_output))
output_0_count = sum(sum(row.count(0) for row in demo_output))

print(f"Input 3s: {input_3_count}")
print(f"Output 8s: {output_8_count}, 1s: {output_1_count}, 0s: {output_0_count}")

# Check if output 8s and 1s correspond to input 3s
print("\nOutput 8 positions that correspond to input 3 positions:")
for i in range(14):
    for j in range(29):
        if demo_output[i][j] == 8 and demo_input[i][j] == 3:
            print(f"  ({i},{j})")

print("\nOutput 1 positions that correspond to input 3 positions:")
for i in range(14):
    for j in range(29):
        if demo_output[i][j] == 1 and demo_input[i][j] == 3:
            print(f"  ({i},{j})")

# Re-verify by checking specific cells
print("Verifying output 8 at position (0,4):")
print(f"  Input (0,4) = {demo_input[0][4]}")
print(f"  Output (0,4) = {demo_output[0][4]}")

print("\nVerifying input 3 positions:")
for i in range(14):
    for j in range(29):
        if demo_input[i][j] == 3:
            is_8_in_output = demo_output[i][j] == 8
            is_1_in_output = demo_output[i][j] == 1
            both_zero = demo_output[i][j] == 0
            print(f"  ({i},{j})=3 -> out: {demo_output[i][j]}")

print("\nCounting what input 3s become:")
become_8 = 0
become_1 = 0
become_0 = 0
for i in range(14):
    for j in range(29):
        if demo_input[i][j] == 3:
            if demo_output[i][j] == 8:
                become_8 += 1
            elif demo_output[i][j] == 1:
                become_1 += 1
            else:
                become_0 += 1
print(f"3s that become 8: {become_8}")
print(f"3s that become 1: {become_1}")
print(f"3s that become 0: {become_0}")

# Find common pattern for output 8 positions
output_8_positions = [
    (0,4), (1,19), (1,24), (1,26), (2,22), (2,28),
    (3,1), (6,0), (6,6), (6,10), (6,19), (9,9),
    (9,17), (9,22), (9,24), (10,0), (10,4), (10,14),
    (10,20), (11,2), (11,11)
]

# Check if they're on diagonals from the input 8/1 sources
sources = [(10,0), (11,0), (12,0)]
source_values = { (10,0): 8, (11,0): 1, (12,0): 1 }

print("Checking if output 8 positions align diagonally from sources:")
for src_r, src_c in sources:
    print(f"\nDiagonals from (r,c)={src_r},{src_c} starting with {source_values[(src_r,src_c)]}:")

    # -45° diagonal (r decreases, c increases)
    print("  -45° (r-+, c+-+):")
    for delta_r in range(-13, 14):
        if delta_r != 0:
            hit_cells = []
            for k in range(1, 15):
                tr, tc = src_r + delta_r, src_c + k*delta_r
                if 0 <= tr < 14 and 0 <= tc < 29:
                    is_8_in_output = any(p == (tr, tc) for p in output_8_positions)
                    if is_8_in_output:
                        hit_cells.append((tr, tc))
            if hit_cells:
                print(f"    Found 8s at: {hit_cells}")

# Check row/column relationships
print("\n\nOutput 8 column indices per row:")
from collections import defaultdict
cols_by_row = defaultdict(list)
for r, c in output_8_positions:
    cols_by_row[r].append(c)
for r in sorted(cols_by_row.keys()):
    print(f"  row {r}: {sorted(cols_by_row[r])}")

# Let me figure out what differentiates row 6's 3s from other 3s
# Row 6 3s: (6,13), (6,16), (6,24), (6,27)
# ALL other 3s create 8s above them

# Maybe it's about being "adjacent" to other 3s?
# Let me check if there's an "adjacent 3" block rule

print("For row 6 3s, check surrounding 3s:")
row6_3s = [(6,13), (6,16), (6,24), (6,27)]
for r3, c3 in row6_3s:
    # Check adjacent 3s in same row
    neighbors_in_row = [c for c in range(c3-2, c3+3) if (r3, c) in row6_3s and c != c3]
    # Check diagonals
    diag_neighbors = []
    for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
        nr, nc = r3 + dr, c3 + dc
        if 0 <= nr < 14 and 0 <= nc < 29:
            if (nr, nc) in input_3_positions:
                diag_neighbors.append((nr, nc))
    print(f"  3 at ({r3},{c3}): row neighbors = {neighbors_in_row}, diag neighbors = {diag_neighbors}")

# Let me check for other 3s that are close to each other
print("\n\nFinding all 3s that are neighbors:")
for r3, c3 in input_3_positions:
    neighbors_in_row = [c for c in range(c3-2, c3+3) if (r3, c) in input_3_positions and c != c3]
    if neighbors_in_row:
        diag_neighbors = []
        for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
            nr, nc = r3 + dr, c3 + dc
            if 0 <= nr < 14 and 0 <= nc < 29:
                if (nr, nc) in input_3_positions:
                    diag_neighbors.append((nr, nc))
        if diag_neighbors or neighbors_in_row:
            print(f"  3 at ({r3},{c3}): row neighbors = {neighbors_in_row}, diag neighbors = {diag_neighbors}")

